  try {
    if (process.argv.length !== 2) throw new Error("usage: node paths.mjs (from workspace)");
    console.log(fs.mkdtempSync(path.join(root(), "run-")));
  } catch (error) { console.error(error.message); process.exitCode = 2; }
}

