  /** Reads from just past an opening quote to its close, or, in a template, to a `${`. */
  const quoted = (q) => {
    const from = i;
    while (i < src.length && src[i] !== q && (q === "`" ? !(src[i] === "$" && src[i + 1] === "{") : src[i] !== "\n")) {
