/** Whether two resolved paths are one file. Windows paths ignore case, and the drive letter's case can differ between the two. */
export const same = (a, b, platform = process.platform) => platform === "win32" ? a.toLowerCase() === b.toLowerCase() : a === b;

if (main(import.meta.url)) {
  try {
    const [run, name] = process.argv.slice(2);
    if (!run || !name || process.argv.length !== 4) throw new Error("usage: node validate.mjs <run> <page.html>");
    const problems = validate(artifactInput(run, name));
    console.log(problems.length ? problems.join("\n") : "Quality lint passed; not a security boundary. Preview unavailable.");
    process.exitCode = problems.length ? 1 : 0;
  } catch (error) { console.error(error.message); process.exitCode = 2; }
}
